"""Extract shared report values/tables from frozen v4. Never writes source inputs."""
from pathlib import Path
import hashlib,json
ROOT=Path(__file__).resolve().parents[3]
BASE=Path(__file__).resolve().parents[1]
PINS={
'reports/release-v4/graph-summary.json':'c6c6e78195500bfaf68cf1f758215824ea239056eefa9ae442edfb0a378b8408',
'reports/release-v4/analysis.json':'580d1a6dbc21ef2ac17b820979830f3de157fc1b04d1c89f2580731f141701c9'}
for rel,h in PINS.items():assert hashlib.sha256((ROOT/rel).read_bytes()).hexdigest()==h,rel
s=json.loads((ROOT/'reports/release-v4/graph-summary.json').read_text());a=json.loads((ROOT/'reports/release-v4/analysis.json').read_text())
c=s['coverage'];counts=s['counts'];p=a['projections'];r=a['release_metrics']
values={
'Papers':c['eligible_papers'],'MatchedWorks':c['papers_with_abstract'],'UnmatchedWorks':c['eligible_papers']-c['papers_with_abstract'],
'TotalNodes':sum(counts['nodes_by_label'].values()),'TotalEdges':sum(counts['edges_by_relation'].values()),
'Researchers':counts['nodes_by_label']['Researcher'],'Organizations':counts['nodes_by_label']['Organization'],
'AcceptedAuthorships':c['author_positions_accepted'],'WithheldAuthorships':c['author_positions_withheld'],
'MatchedPositions':c['author_positions'],'OfficialPositions':c['official_author_positions_all_roster_papers'],
'AffiliatedPositions':c['accepted_authorships_with_institution'],'LabeledPapers':c['papers_topic_labeled'],
'AbstainedPapers':c['papers_topic_abstained'],'TopicEdges':counts['edges_by_relation']['HAS_TOPIC'],
'CoauthorPairs':counts['edges_by_relation']['COAUTHORED_WITH'],'OrganizationPairs':counts['edges_by_relation']['COLLABORATED_WITH'],
'CitationEdges':counts['edges_by_relation']['CITES'],'ResearcherIsolates':p['researcher_collaboration']['isolate_count'],
'ResearcherComponents':len(p['researcher_collaboration']['weak_or_undirected_component_sizes']),
'LargestComponent':max(p['researcher_collaboration']['weak_or_undirected_component_sizes']),
'OrganizationIsolates':p['organization_collaboration']['isolate_count'],'CitationIsolates':p['core_citations']['isolate_count']}
(BASE/'data/facts.tex').write_text('% Generated by scripts/prepare-data.py from frozen production v4.\n'+''.join('\\newcommand{\\'+k+'}{\\num{'+str(v)+'}}\n' for k,v in values.items()))

def num(n):return r'\num{'+str(n)+'}'
def table(name,caption,label,columns,header,rows):
 text=r'\begin{table}[!htbp]\centering\small'+'\n'+r'\caption{'+caption+r'}\label{'+label+'}\n'+r'\begin{tabularx}{\textwidth}{'+columns+'}\n'+r'\toprule '+header+r'\\\midrule'+'\n'+'\n'.join(' & '.join(row)+r'\\' for row in rows)+'\n'+r'\bottomrule\end{tabularx}\end{table}'+'\n'
 (BASE/f'tables/bilingual-{name}.tex').write_text('% Generated from frozen v4; edit generator.\n'+text)
node_trans={'Researcher':'Nhà nghiên cứu','Paper':'Bài báo','Organization':'Tổ chức','Topic':'Chủ đề','Venue':'Hội nghị'}
table('nodes',r'\lang{Graph nodes by type.}{Số nút theo loại thực thể.}','tab:nodes','Yr',r'\lang{Entity type}{Loại thực thể} & \lang{Nodes}{Số nút}',[[r'\lang{'+k+'}{'+node_trans[k]+'}',num(v)] for k,v in counts['nodes_by_label'].items()]+[[r'\textbf{\lang{Total}{Tổng}}',num(values['TotalNodes'])]])
classes={'AUTHORED':('Observed','Quan sát'),'AFFILIATED_WITH':('Observed','Quan sát'),'PUBLISHED_IN':('Observed','Quan sát'),'CITES':('Observed','Quan sát'),'HAS_TOPIC':('Inferred','Suy ra từ mô hình'),'SUBTOPIC_OF':('Curated','Biên soạn'),'COAUTHORED_WITH':('Derived','Dẫn xuất'),'COLLABORATED_WITH':('Derived','Dẫn xuất'),'RESEARCHES_TOPIC':('Derived','Dẫn xuất'),'CONTRIBUTES_TO_TOPIC':('Derived','Dẫn xuất')}
rows=[]
for k,(en,vi) in classes.items():rows.append([r'\texttt{'+k.replace('_',r'\_')+'}',r'\lang{'+en+'}{'+vi+'}',num(counts['edges_by_relation'][k])])
rows.append([r'\textbf{\lang{Total}{Tổng}}','',num(values['TotalEdges'])])
table('edges',r'\lang{Accepted edges by predicate and evidence class.}{Các cạnh được chấp nhận theo quan hệ và loại bằng chứng.}','tab:edges','Ylr',r'\lang{Predicate}{Quan hệ} & \lang{Evidence}{Bằng chứng} & \lang{Edges}{Số cạnh}',rows)
rows=[]
for x in r['annual_counts']['rows']:rows.append([str(x['year']),num(x['active_researcher_count']),num(x['new_collaboration_pair_count'])])
table('annual',r'\lang{Annual activity in the accepted coauthorship network.}{Hoạt động hằng năm trong mạng đồng tác giả được chấp nhận.}','tab:annual','rYY',r'\lang{Year}{Năm} & \lang{Active researchers}{Nhà nghiên cứu hoạt động} & \lang{First-observed pairs}{Cặp xuất hiện lần đầu}',rows)
rows=[]
for x in r['bridge_researchers']['top_researchers'][:5]:rows.append([x['researcher'],f"{x['betweenness']:.6f}",x['community_id'].split(':')[1],num(x['community_member_count'])])
table('bridges',r'\lang{Leading approximate weighted-betweenness records and community context.}{Các định danh đứng đầu theo độ trung tâm trung gian xấp xỉ có trọng số và cộng đồng tương ứng.}','tab:bridges','Yrrr',r'\lang{Researcher}{Nhà nghiên cứu} & \lang{Betweenness}{\makecell[r]{Độ trung tâm\\trung gian}} & \lang{Community}{Cộng đồng} & \lang{Members}{Số thành viên}',rows)
(BASE/'data/fact-manifest.json').write_text(json.dumps({'graph_version':s['graph_version'],'inputs_sha256':PINS,'values':values},indent=2)+'\n')
print('Shared facts and four bilingual tables generated from frozen v4.')
